            Llm,
            baseConocimiento,
            new AuditorPeticiones(Auditoria, reloj),
            new PoliticaAcceso(),
            new VerificadorSalida(),
            limites,
            new ConfiguracionAsistente(null, canario, datos.Directorio.CodigosAsignatura),
            new PresupuestoDiario(reloj, limites));
    }

