using System.Text.Json;

namespace TutorFlow.Evals;

public sealed record UsuarioEval(string Rol, string Id);

public sealed record GuionOffline(string Herramientas, string? EstudianteIdCoordinador, string? Texto);

public sealed record CasoEval(
    string Id,
    string Fuente,
    UsuarioEval Usuario,
    string Pregunta,
    int Http,
    IReadOnlyList<string> Contiene,
    IReadOnlyList<string> NoContiene,
    IReadOnlyList<string> CitasIncluye,
    IReadOnlyList<string> CitasProhibidas,
    bool CitasVacias,
    IReadOnlyList<string>? CitasExactas,
    int? CitasTotal,
    bool? UsoDatosEstudiante,
    string? RespuestaExacta,
    bool TokensCero,
    bool FiltroPrevio,
    bool RequiereLlm,
    bool SoloOffline,
    GuionOffline? Offline)
{
    public string Etiqueta => $"{Id} [{Usuario.Rol}:{Usuario.Id}] {Resumen(Pregunta)}";

    private static string Resumen(string texto) => texto.Length <= 48 ? texto : texto[..48] + "...";
}

public sealed record OpcionesEvals(string Url, bool Offline, string RutaCasos, int Corridas, int PausaMs, int UmbralP95Ms, string? Filtro);

public sealed record Ejecucion(int Estado, string Cuerpo, double Milisegundos);

public sealed record ResultadoCaso(CasoEval Caso, int Corrida, IReadOnlyList<string> Fallos, Ejecucion? Ejecucion)
{
    public bool Omitido => Ejecucion is null;

    public bool Aprobado => !Omitido && Fallos.Count == 0;
}

public sealed record CitaEval(string Documento, string Seccion)
{
    public string Texto => $"{Documento} · {Seccion}";
}

public sealed record SalidaEval(string? Respuesta, IReadOnlyList<CitaEval>? Citas, bool UsoDatosEstudiante, int Tokens, decimal CostoUsd);

public static class Json
{
    public static readonly JsonSerializerOptions Opciones = new(JsonSerializerDefaults.Web);

    public static SalidaEval? LeerSalida(string cuerpo)
    {
        try
        {
            return JsonSerializer.Deserialize<SalidaEval>(cuerpo, Opciones);
        }
        catch (JsonException)
        {
            return null;
        }
    }
}
using System.Diagnostics;
using System.Text;
using System.Text.Json;
using TutorFlow.Api.Tests;
using TutorFlow.Api.Tests.Dobles;
using TutorFlow.Core.Asistente;

namespace TutorFlow.Evals;

public interface IEjecutor
{
    Task<Ejecucion?> EjecutarAsync(CasoEval caso, CancellationToken cancellationToken);
}

public static class Cuerpos
{
    public const string Ruta = "/api/asistente/preguntar";

    public static string De(CasoEval caso) =>
        JsonSerializer.Serialize(new { pregunta = caso.Pregunta, usuario = new { rol = caso.Usuario.Rol, id = caso.Usuario.Id } });
}

public sealed class EjecutorHttp : IEjecutor
{
    private readonly HttpClient _cliente;
    private readonly int _pausaMs;

    public EjecutorHttp(HttpClient cliente, int pausaMs)
    {
        _cliente = cliente;
        _pausaMs = pausaMs;
    }

    public async Task<Ejecucion?> EjecutarAsync(CasoEval caso, CancellationToken cancellationToken)
    {
        if (caso.SoloOffline)
        {
            return null;
        }

        await Task.Delay(_pausaMs, cancellationToken);
        var reloj = Stopwatch.StartNew();
        using var contenido = new StringContent(Cuerpos.De(caso), Encoding.UTF8, "application/json");
        using var respuesta = await _cliente.PostAsync(Cuerpos.Ruta, contenido, cancellationToken);
        var texto = await respuesta.Content.ReadAsStringAsync(cancellationToken);
        reloj.Stop();
        return new Ejecucion((int)respuesta.StatusCode, texto, reloj.Elapsed.TotalMilliseconds);
    }
}

public sealed class EjecutorEnProceso : IEjecutor
{
    private const string MarcadorHerramientas = "{herramientas}";

    public async Task<Ejecucion?> EjecutarAsync(CasoEval caso, CancellationToken cancellationToken)
    {
        if (caso.RequiereLlm && caso.Offline is null)
        {
            return null;
        }

        using var fabrica = new FabricaApi(llm: LlmPara(caso.Offline), conocimientoReal: true, configuracion: FabricaApi.Precios("0.10", "0.50"));
        var reloj = Stopwatch.StartNew();
        var respuesta = await fabrica.EnviarAsync(HttpMethod.Post, Cuerpos.Ruta, Cuerpos.De(caso));
        reloj.Stop();
        return new Ejecucion(respuesta.Estado, respuesta.Texto, reloj.Elapsed.TotalMilliseconds);
    }

    private static ClienteLlmDoble LlmPara(GuionOffline? guion)
    {
        if (guion is null)
        {
            return ClienteLlmDoble.Texto(Textos.SinInformacion);
        }

        return guion.Herramientas == "todas"
            ? ClienteLlmDoble.ConsultaDatos(guion.EstudianteIdCoordinador, solicitud => Plantilla(guion.Texto, solicitud))
            : ClienteLlmDoble.Texto(guion.Texto ?? Textos.SinInformacion);
    }

    private static string Plantilla(string? texto, SolicitudLlm solicitud) =>
        (texto ?? MarcadorHerramientas).Replace(MarcadorHerramientas, ClienteLlmDoble.EcoDeHerramientas(solicitud), StringComparison.Ordinal);
}

