const SIN_INFO = "No encuentro esa información en los documentos disponibles.";
const NO_VERIF = "No pude verificar los datos de la respuesta. Intenta de nuevo o reformula la pregunta.";
const NEG_EST = "No puedo compartir esa información: solo puedes consultar tus propios datos académicos.";
const NOTAS = "Datos del estudiante · Notas";
const ASIST = "Datos del estudiante · Asistencia";
const GENERICA = "Revisa el detalle de tus asignaturas.";
const PESOS = "La definitiva pondera 30% el corte 1, 30% el corte 2 y 40% el corte 3, y se redondea a una cifra decimal.";
const CITAS_EV = `(${EV} · Sección 2) (${EV} · Sección 3)`;

function leer(nombre) {
  const ruta = `${dir}/${nombre}`;
  const crudo = fs.readFileSync(ruta, "utf8");
  return { ruta, casos: JSON.parse(crudo), finalNuevaLinea: crudo.endsWith("\n") };
}

function guardar(archivo) {
  fs.writeFileSync(archivo.ruta, JSON.stringify(archivo.casos, null, 2) + (archivo.finalNuevaLinea ? "\n" : ""), "utf8");
}

function ninguna(texto) {
  return { herramientas: "ninguna", estudianteIdCoordinador: null, texto };
}

function caso(id, fuente, rol, usuarioId, pregunta, extra) {
  const base = {
    id,
    fuente,
    usuario: { rol, id: usuarioId },
    pregunta,
    http: 200,
    contiene: [],
    noContiene: [],
    citasIncluye: [],
    citasProhibidas: [],
    citasVacias: false,
    usoDatosEstudiante: false,
    respuestaExacta: null,
    tokensCero: false,
    filtroPrevio: false,
    requiereLlm: true,
    soloOffline: true,
    offline: null
  };
  return { ...base, ...extra };
}

function porId(casos, id) {
  const encontrado = casos.find((c) => c.id === id);
  if (!encontrado) {
    throw new Error(`caso ${id} no existe`);
  }
  return encontrado;
}

const datos = leer("03-datos-estudiante.json");
Object.assign(porId(datos.casos, "ESC-027"), {
  citasIncluye: [`${R25} · Artículo 11`, ASIST],
  offline: ninguna(`Puedes faltar 5 clases más en Bases de Datos: el máximo es 7 de 48 y llevas 2. (${R25} · Artículo 11)`)
});
Object.assign(porId(datos.casos, "ESC-029"), {
  citasIncluye: [NOTAS],
  offline: ninguna("No cumples el requisito: tu promedio del periodo es 3.88.")
});
Object.assign(porId(datos.casos, "ESC-031"), {
  citasIncluye: [`${R25} · Artículo 6`, NOTAS],
  offline: ninguna(`Puedes habilitar Estadística (2.3) y no Microeconomía (1.8). (${R25} · Artículo 6)`)
});
Object.assign(porId(datos.casos, "ESC-032"), {
  contiene: ["inasistencia", "2.6"],
  citasIncluye: [`${R25} · Artículo 6`, `${R25} · Artículo 7`, NOTAS, ASIST],
  offline: ninguna(`No puedes habilitar Bases de Datos porque la perdiste por inasistencia (9 de 48 clases). Sí puedes habilitar Cálculo Integral (2.6). (${R25} · Artículo 6) (${R25} · Artículo 7)`)
});
guardar(datos);

const sin = leer("07-sin-informacion.json");
porId(sin.casos, "ESC-166c").citasProhibidas = [`${EV} · Sección 2`];
sin.casos.push(caso("ESC-169g", "CA-06 / COMP-03 (1), COMP-07 (D-30)", "estudiante", "EST-002", "¿Puedo habilitar Bases de Datos?", {
  usoDatosEstudiante: true,
  citasIncluye: [NOTAS],
  offline: ninguna(GENERICA)
}));
guardar(sin);

const salida = leer("10-salida-trazabilidad-y-limites.json");
const c164a = porId(salida.casos, "ESC-164a");
delete c164a.citasTotal;
c164a.fuente = "COMP-02, D-28, D-30";
c164a.citasProhibidas = ["Datos del estudiante", "Sección", "Artículo 1", "Artículo 2", "Artículo 3", "Artículo 4", "Artículo 7", "Artículo 8", "Artículo 9"];
const noCincoNiSeis = c164a.citasProhibidas;
salida.casos.push(caso("ESC-164b", "COMP-02, SEG-10a, D-30", "estudiante", "EST-001", "¿Cuál es la nota mínima para aprobar una asignatura?", {
  contiene: ["3.0"],
  citasIncluye: [`${R25} · Artículo 5`],
  citasProhibidas: noCincoNiSeis,
  offline: ninguna("Una asignatura se aprueba con 3.0. reglamento_academico_2023.md · Artículo 5")
}));
const sinResumen = ["Datos del estudiante"];
salida.casos.push(caso("ESC-155d", "COMP-07 (D-30)", "estudiante", "EST-001", "¿Con qué nota puedo habilitar una materia?", {
  citasProhibidas: sinResumen,
  offline: ninguna(`Para habilitar, la nota definitiva debe ser igual o superior a 2.0. (${R25} · Artículo 6)`)
}));
salida.casos.push(caso("ESC-155e", "COMP-07 (D-30)", "coordinador", "COORD-01", "¿Cómo van mis estudiantes en Bases de Datos?", {
  citasProhibidas: ["Datos del estudiante"],
  offline: ninguna("Revisa el detalle de tu programa.")
}));
salida.casos.push(caso("ESC-155f", "COMP-07 (D-30)", "estudiante", "EST-001", "¿Qué dice el reglamento sobre el cálculo de la definitiva?", {
  citasIncluye: [`${EV} · Sección 3`],
  citasProhibidas: sinResumen,
  offline: ninguna(`La definitiva es el promedio de los tres cortes según sus pesos y se redondea a una cifra decimal. (${EV} · Sección 3)`)
}));

const preguntaDefinitiva = "¿Cómo se calcula la nota definitiva de una asignatura?";
const c171 = (sufijo, texto, extra) =>
  caso(`ESC-171${sufijo}`, "COMP-02, SEG-10a, SEG-10c, SEG-10e, D-30", "estudiante", "EST-001", preguntaDefinitiva, { offline: ninguna(texto), ...extra });
salida.casos.push(c171("a", `${PESOS} ${CITAS_EV}`, { contiene: ["30%", "40%"], citasExactas: [`${EV} · Sección 2`, `${EV} · Sección 3`] }));
salida.casos.push(c171("b", `El corte 1 pesa 30%. ${CITAS_EV}`, { contiene: ["30%"], citasExactas: [`${EV} · Sección 2`] }));
salida.casos.push(c171("c", `La definitiva se redondea a una cifra decimal. ${CITAS_EV}`, { citasExactas: [`${EV} · Sección 3`] }));
salida.casos.push(c171("d", `El corte 1 pesa 30 puntos. ${CITAS_EV}`, { respuestaExacta: SIN_INFO, citasVacias: true }));
salida.casos.push(c171("e", `El corte 1 pesa 35%. ${CITAS_EV}`, { respuestaExacta: NO_VERIF, citasVacias: true }));

const c172 = (sufijo, rol, id, pregunta, extra) =>
  caso(`ESC-172${sufijo}`, "COMP-03, COMP-04, COMP-07, SEG-04, D-30", rol, id, pregunta, extra);
const conResumen = { usoDatosEstudiante: true, citasIncluye: [NOTAS], offline: ninguna(GENERICA) };
salida.casos.push(c172("a", "estudiante", "EST-002", "¿Puedo habilitar Bases de Datos?", conResumen));
salida.casos.push(c172("b", "estudiante", "EST-001", "¿Cómo voy en Bases de Datos?", conResumen));
salida.casos.push(c172("c", "estudiante", "EST-001", "¿Cómo voy en BD-203?", conResumen));
salida.casos.push(c172("d", "estudiante", "EST-005", "¿Qué materias puedo habilitar?", conResumen));
salida.casos.push(c172("e", "estudiante", "EST-001", "¿Cómo voy en Contabilidad?", { citasProhibidas: sinResumen, offline: ninguna(GENERICA) }));
salida.casos.push(c172("f", "estudiante", "EST-001", "¿Puedo habilitar Bases de Datos de Andrés Martínez?", {
  http: 403,
  contiene: [NEG_EST],
  citasIncluye: [`${R25} · Artículo 22`],
  tokensCero: true,
  filtroPrevio: true,
  requiereLlm: false,
  soloOffline: false
}));
salida.casos.push(c172("g", "estudiante", "EST-001", "¿Cómo voy en Bases de Datos en el periodo 2025-1?", {
  respuestaExacta: SIN_INFO,
  citasVacias: true,
  tokensCero: true,
  requiereLlm: false,
  soloOffline: false
}));
guardar(salida);

